<?php defined( 'ABSPATH' ) || exit;
$summary = $reviews['summary'] ?? array( 'count' => 0, 'average' => 0, 'distribution' => array() );
$count = (int) $summary['count'];
$write_url = Petish_Customer_Reviews_UI::url( array( 'pcr_product' => $product->get_id() ) ) . '#pcr-composer';
$filter_url = get_permalink( $product->get_id() );
$pagination_url = add_query_arg( array( 'pcr_sort' => $filters['sort'], 'pcr_media' => $filters['media'], 'pcr_rating' => $filters['rating'], 'pcr_verified' => $filters['verified'] ? '1' : '0' ), $filter_url );
?>
<section id="petish-customer-reviews" class="pcr pcr-product" aria-labelledby="pcr-product-title">
    <span id="reviews" aria-hidden="true"></span>
    <header class="pcr-heading"><div><p class="pcr-eyebrow"><?php esc_html_e( 'From our small-pet people', 'petish-passport' ); ?></p><h2 id="pcr-product-title"><?php esc_html_e( 'Little pets. Honest stories.', 'petish-passport' ); ?></h2><p><?php esc_html_e( 'First-hand experiences to help you choose with a little more confidence.', 'petish-passport' ); ?></p></div><a class="pcr-button" href="<?php echo esc_url( is_user_logged_in() ? $write_url : wp_login_url( $write_url ) ); ?>"><?php echo esc_html( is_user_logged_in() ? __( 'Write a review', 'petish-passport' ) : __( 'Sign in to review', 'petish-passport' ) ); ?> <span aria-hidden="true">→</span></a></header>
    <div class="pcr-product-grid"><div>
        <div class="pcr-rating-summary" aria-label="<?php esc_attr_e( 'Community review ratings', 'petish-passport' ); ?>">
            <div><strong class="pcr-average"><?php echo $count ? esc_html( number_format_i18n( (float) $summary['average'], 1 ) ) : '—'; ?></strong><span class="pcr-muted"> / 5</span><p class="pcr-small"><?php echo esc_html( sprintf( _n( '%s community review', '%s community reviews', $count, 'petish-passport' ), number_format_i18n( $count ) ) ); ?></p></div>
            <div class="pcr-bars"><?php for ( $rating = 5; $rating >= 1; $rating-- ) : $amount = (int) ( $summary['distribution'][ $rating ] ?? 0 ); ?><div class="pcr-bar"><span><?php echo esc_html( $rating ); ?> ★</span><meter min="0" max="<?php echo esc_attr( max( 1, $count ) ); ?>" value="<?php echo esc_attr( $amount ); ?>" aria-label="<?php echo esc_attr( sprintf( __( '%1$d-star reviews: %2$d', 'petish-passport' ), $rating, $amount ) ); ?>"><?php echo esc_html( $amount ); ?></meter><span><?php echo esc_html( number_format_i18n( $amount ) ); ?></span></div><?php endfor; ?></div>
        </div>
        <form class="pcr-filters" method="get" action="<?php echo esc_url( $filter_url ); ?>#petish-customer-reviews">
            <label><?php esc_html_e( 'Rating', 'petish-passport' ); ?><select name="pcr_rating"><option value="0"><?php esc_html_e( 'All ratings', 'petish-passport' ); ?></option><?php for ( $i = 5; $i >= 1; $i-- ) : ?><option value="<?php echo esc_attr( $i ); ?>" <?php selected( $filters['rating'], $i ); ?>><?php echo esc_html( sprintf( _n( '%d star', '%d stars', $i, 'petish-passport' ), $i ) ); ?></option><?php endfor; ?></select></label>
            <label><?php esc_html_e( 'Media', 'petish-passport' ); ?><select name="pcr_media"><?php foreach ( array( 'all' => __( 'All reviews', 'petish-passport' ), 'photos' => __( 'With photos', 'petish-passport' ), 'video' => __( 'With video', 'petish-passport' ) ) as $key => $label ) : ?><option value="<?php echo esc_attr( $key ); ?>" <?php selected( $filters['media'], $key ); ?>><?php echo esc_html( $label ); ?></option><?php endforeach; ?></select></label>
            <label><?php esc_html_e( 'Sort by', 'petish-passport' ); ?><select name="pcr_sort"><?php foreach ( array( 'newest' => __( 'Most recent', 'petish-passport' ), 'oldest' => __( 'Oldest first', 'petish-passport' ), 'highest' => __( 'Highest rating', 'petish-passport' ), 'lowest' => __( 'Lowest rating', 'petish-passport' ) ) as $key => $label ) : ?><option value="<?php echo esc_attr( $key ); ?>" <?php selected( $filters['sort'], $key ); ?>><?php echo esc_html( $label ); ?></option><?php endforeach; ?></select></label>
            <label class="pcr-check"><input type="checkbox" name="pcr_verified" value="1" <?php checked( $filters['verified'] ); ?>> <span><?php esc_html_e( 'Verified purchase', 'petish-passport' ); ?></span></label><button class="pcr-button pcr-secondary" type="submit"><?php esc_html_e( 'Apply filters', 'petish-passport' ); ?></button>
        </form>
        <div class="pcr-review-list"><?php if ( empty( $reviews['items'] ) ) : ?><div class="pcr-empty"><h3><?php echo esc_html( $count ? __( 'No reviews match these filters.', 'petish-passport' ) : __( 'Their first little story starts with you.', 'petish-passport' ) ); ?></h3><p><?php echo esc_html( $count ? __( 'Try another rating or media filter.', 'petish-passport' ) : __( 'Used this product? Share what worked for your pet and anything you would have liked to know.', 'petish-passport' ) ); ?></p></div><?php else : foreach ( $reviews['items'] as $review ) { Petish_Customer_Reviews_UI::template( 'card', array( 'review' => $review, 'owner' => false ) ); } endif; ?></div>
        <?php Petish_Customer_Reviews_UI::pagination( $reviews, $pagination_url ); ?>
        <?php if ( ! empty( $legacy['total'] ) ) : ?>
        <section class="pcr-earlier" id="pcr-earlier" aria-labelledby="pcr-earlier-title"><h3 id="pcr-earlier-title"><?php esc_html_e( 'Earlier reviews', 'petish-passport' ); ?></h3><p class="pcr-small"><?php esc_html_e( 'Customer reviews shared before Petish’s reviewer programme.', 'petish-passport' ); ?></p>
            <?php foreach ( $legacy['items'] as $old ) : $old_rating = (int) get_comment_meta( $old->comment_ID, 'rating', true ); ?><article class="pcr-review"><header class="pcr-review-head"><strong><?php echo esc_html( $old->comment_author ); ?></strong><time datetime="<?php echo esc_attr( get_comment_date( 'c', $old ) ); ?>"><?php echo esc_html( get_comment_date( '', $old ) ); ?></time></header><?php if ( $old_rating ) { echo Petish_Customer_Reviews_UI::stars( $old_rating ); } ?><div class="pcr-review-body"><?php echo wpautop( esc_html( $old->comment_content ) ); ?></div></article><?php endforeach; ?>
            <?php Petish_Customer_Reviews_UI::pagination( $legacy, $pagination_url, 'pcr_earlier', 'pcr-earlier' ); ?>
        </section><?php endif; ?>
    </div><aside class="pcr-sidebar" aria-label="<?php esc_attr_e( 'Reviewer information', 'petish-passport' ); ?>">
        <?php if ( is_array( $metrics ) ) : Petish_Customer_Reviews_UI::template( 'progress', array( 'metrics' => $metrics ) ); else : ?><div class="pcr-panel pcr-soft"><p class="pcr-eyebrow"><?php esc_html_e( 'A little more together', 'petish-passport' ); ?></p><h3><?php esc_html_e( 'Share what you know.', 'petish-passport' ); ?></h3><p><?php esc_html_e( 'Join the community to review products, share photos and videos, and follow your contributions.', 'petish-passport' ); ?></p><a href="<?php echo esc_url( wp_login_url( $write_url ) ); ?>"><?php esc_html_e( 'Sign in to get started', 'petish-passport' ); ?> →</a></div><?php endif; ?>
        <div class="pcr-panel"><h3><?php esc_html_e( 'Honest experiences come first.', 'petish-passport' ); ?></h3><p><?php esc_html_e( 'One star or five, every genuine experience matters. Text, photos and videos are moderated before publication.', 'petish-passport' ); ?></p><p class="pcr-small"><?php esc_html_e( 'Reviewer status recognises contributions. It is not a guarantee of expertise or product suitability.', 'petish-passport' ); ?></p></div>
    </aside></div>
</section>
